"use client";
import { ArtemisScope } from "./artemis-scope";
import View0 from "./components/credit-usage/variants/01-trend";
import View1 from "./components/credit-usage/variants/02-breakdown";
const variants={"trend":View0,"breakdown":View1};
export interface ArtemisCreditUsageProps { className?: string; variant?: "trend" | "breakdown"; }
export function ArtemisCreditUsage({className,variant="trend"}:ArtemisCreditUsageProps) {const View=variants[variant];return <ArtemisScope className={className}><div className="art:flex art:w-full art:min-w-0 art:flex-col art:items-center"><View/></div></ArtemisScope>;}
